#!/usr/bin/env bash
# Lane 4 — INSERT throughput (WAL-backed, single writer).
#
# Measurement method (deterministic, reproducible):
#   * Target opens a brand-new file DB in a tmpdir (nuked after the run).
#   * workload.sql (generated by generate-corpus.sh, seed 0xBEEFCAFE) sets
#     WAL mode + synchronous=NORMAL, creates one table, then does 100 000
#     INSERTs inside a single transaction. One writer only.
#   * Wall-clock the whole run, divide by 100 000 to get inserts/sec.
#   * Each repetition uses a FRESH tmpdir so we measure steady-state WAL
#     write cost on a clean file (no page cache reuse across runs).
#   * Median of 5 runs, 1 warmup.
#
# Caveats documented for publication:
#   - SSD performance dominates. Pin the host or disable Turbo for stable
#     numbers; CSV captures the value, not the conditions — those go in the
#     publication write-up.
#
# Output: insert-throughput,<target>,<inserts_per_second>,inserts_per_second,<iso8601>

set -euo pipefail
SCRIPT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
# shellcheck disable=SC1091
source "$SCRIPT_DIR/../_lib.sh"

LANE_NAME="insert-throughput"
parse_target_flag "$@"

WORKLOAD="$SCRIPT_DIR/workload.sql"
if [[ ! -f "$WORKLOAD" ]]; then
    "$SCRIPT_DIR/generate-corpus.sh" >&2
fi
ROWS=100000

bin="$(binary_for_target "$TARGET" || true)"
[[ -z "$bin" ]] && emit_missing "$LANE_NAME" "$TARGET" && exit 1

# We wrap the per-run invocation in a shell snippet that creates a fresh
# tmpdir, runs the workload against a file DB there, and cleans up. Timing
# captures the full lifecycle — identical setup cost across targets.
case "$TARGET" in
    sqlite-mainline|turso)
        invoke="d=\$(mktemp -d); $bin \$d/db.sqlite < $WORKLOAD > /dev/null; rm -rf \$d"
        ;;
    sqlite-leap-c|sqlite-leap-rust)
        # See bench/lanes/_wrap_sql.py for why per-statement wrapping is
        # required. Pre-2026-04-20 the whole workload was wrapped under
        # a single `statement ok` header and the runner failed fast on
        # the second statement.
        wrapped="$SCRIPT_DIR/workload.slt"
        if [[ ! -f "$wrapped" || "$WORKLOAD" -nt "$wrapped" ]]; then
            python3 "$BENCH_ROOT/lanes/_wrap_sql.py" "$WORKLOAD" "$wrapped" >&2
        fi
        # sqllogictest harness creates its own DB per run; pass the workload.
        invoke="$bin $wrapped > /dev/null"
        ;;
esac

cmd=(bash -c "$invoke")
median_seconds="$(time_median 5 1 -- "${cmd[@]}")"
ips="$(python3 -c "print(int(${ROWS}/${median_seconds}))")"
emit_csv "$LANE_NAME" "$TARGET" "$ips" "inserts_per_second"
